"""Steps CLI subcommands."""

from __future__ import annotations

import typer
from typing import Any

from core.models import Step

steps_app = typer.Typer(help="Manage Step entities.")


@steps_app.command("add")
def add_step(
    job_id: str = typer.Option(..., help="Job ID the step belongs to"),
    name: str = typer.Option(..., help="Step name"),
    order: int = typer.Option(..., help="Step order"),
    mcp_url: str = typer.Option(
        ..., help="MCP server URL", callback=lambda ctx, val: val
    ),
) -> None:
    """Add a Step to a Job."""
    from cli.backend import get_backend

    typer.echo(
        get_backend("local", db_path=None, mcp_url=mcp_url).call(
            "add_step", {"job_id": job_id, "name": name, "order": order}
        )
    )


@steps_app.command("list")
def list_steps(
    job_id: str = typer.Option(..., help="Job ID to list steps for"),
    mcp_url: str = typer.Option(
        ..., help="MCP server URL", callback=lambda ctx, val: val
    ),
) -> None:
    """List Steps for a Job."""
    from cli.backend import get_backend

    typer.echo(
        get_backend("local", db_path=None, mcp_url=mcp_url).call(
            "get_job_map", {"job_id": job_id}
        )
    )


@steps_app.command("get")
def get_step(
    step_id: str = typer.Argument(...),
    mcp_url: str = typer.Option(
        ..., help="MCP server URL", callback=lambda ctx, val: val
    ),
) -> None:
    """Get a Step by ID."""
    from cli.backend import get_backend

    typer.echo(
        get_backend("local", db_path=None, mcp_url=mcp_url).call(
            "get_step", {"step_id": step_id}
        )
    )


@steps_app.command("update")
def update_step(
    step_id: str = typer.Argument(...),
    name: str | None = typer.Option(default=None, help="Step name"),
    order: int | None = typer.Option(default=None, help="Step order"),
    mcp_url: str = typer.Option(
        ..., help="MCP server URL", callback=lambda ctx, val: val
    ),
) -> None:
    """Update a Step."""
    from cli.backend import get_backend

    args: dict[str, Any] = {}
    if name is not None:
        args["name"] = name
    if order is not None:
        args["order"] = order

    typer.echo(
        get_backend("local", db_path=None, mcp_url=mcp_url).call(
            "update_step", {"step_id": step_id, **args}
        )
    )


